//! Golden `compute_scale_q16_16` vectors generated by the C reference engine
//! (`tests/gen_vectors.c`); see `vectors/README.md`. Embedded with
//! `include_str!` so the test also runs on `wasm32-wasip1`.

use kf_dirgain::{PROFILE_LEN, Profile, compute_scale_q16_16};
use serde_json::Value;

const VECTORS: &str = include_str!("vectors/scale_vectors.json");

fn profile_bytes(hex: &str) -> [u8; PROFILE_LEN] {
    assert_eq!(
        hex.len(),
        2 * PROFILE_LEN,
        "bytes must be {PROFILE_LEN} hex pairs"
    );
    let mut out = [0u8; PROFILE_LEN];
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).expect("hex byte");
    }
    out
}

#[test]
fn scale_vectors_match_c_reference() {
    let doc: Value = serde_json::from_str(VECTORS).expect("valid JSON");
    assert_eq!(
        doc["vector_fields"],
        serde_json::json!(["dx", "dy", "scale_q16_16", "octant"])
    );
    let profiles = doc["profiles"].as_array().expect("profiles array");
    assert_eq!(profiles.len(), 8);

    let mut checked = 0;
    for p in profiles {
        let name = p["name"].as_str().expect("profile name");
        let bytes = profile_bytes(p["bytes"].as_str().expect("profile bytes"));
        let profile = Profile::deserialize(&bytes)
            .unwrap_or_else(|| panic!("{name}: deserialize rejected the profile"));
        assert_eq!(profile.serialize(), bytes, "{name}: serialize round trip");

        for v in p["vectors"].as_array().expect("vectors array") {
            let field = |i: usize| v[i].as_i64().expect("integer field");
            let dx = i16::try_from(field(0)).expect("dx fits i16");
            let dy = i16::try_from(field(1)).expect("dy fits i16");
            let expected = (
                u32::try_from(field(2)).expect("scale fits u32"),
                u8::try_from(field(3)).expect("octant fits u8"),
            );
            assert_eq!(
                compute_scale_q16_16(&profile, dx, dy),
                expected,
                "{name}: vector {v} (dx, dy) = ({dx}, {dy}) -> (scale, octant)"
            );
            checked += 1;
        }
    }
    assert_eq!(checked, 2592);
}
